<?php
require 'config.php'; require 'includes/functions.php'; $pdo=db(); $action=$_GET['action']??'list'; $id=(int)($_GET['id']??0); $errors=[]; $book=['title'=>'','author'=>'','isbn'=>'','category'=>'','quantity'=>'1'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$fa=$_POST['form_action']??'';
 if($fa==='delete'){try{$s=$pdo->prepare('DELETE FROM books WHERE id=?');$s->execute([(int)$_POST['id']]);flash('success','Book deleted.');}catch(Throwable $e){flash('danger','This book has loan history and cannot be deleted.');}redirect('books.php');}
 $id=(int)($_POST['id']??0);$book=['title'=>trim($_POST['title']??''),'author'=>trim($_POST['author']??''),'isbn'=>trim($_POST['isbn']??''),'category'=>trim($_POST['category']??''),'quantity'=>filter_var($_POST['quantity']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>0]])];
 foreach(['title'=>'Title','author'=>'Author','isbn'=>'ISBN','category'=>'Category'] as $k=>$label)if($book[$k]==='')$errors[]="$label is required.";
 if($book['quantity']===false)$errors[]='Quantity must be a whole number of zero or more.';
 if(!$errors){try{if($fa==='update'){$s=$pdo->prepare('UPDATE books SET title=?,author=?,isbn=?,category=?,quantity=?,available=available+(?-quantity) WHERE id=?');$s->execute([$book['title'],$book['author'],$book['isbn'],$book['category'],$book['quantity'],$book['quantity'],$id]);flash('success','Book updated.');}else{$s=$pdo->prepare('INSERT INTO books(title,author,isbn,category,quantity,available) VALUES(?,?,?,?,?,?)');$s->execute([$book['title'],$book['author'],$book['isbn'],$book['category'],$book['quantity'],$book['quantity']]);flash('success','Book added.');}redirect('books.php');}catch(PDOException $e){$errors[]='Could not save. ISBN must be unique.';}}
 $action=$fa==='update'?'edit':'add';
}
if($action==='edit'&&$id&&$_SERVER['REQUEST_METHOD']!=='POST'){$s=$pdo->prepare('SELECT * FROM books WHERE id=?');$s->execute([$id]);$found=$s->fetch();if($found)$book=$found;else{flash('warning','Book not found.');redirect('books.php');}}
$q=trim($_GET['q']??'');if($action==='list'){$sql='SELECT * FROM books';$params=[];if($q!==''){$sql.=' WHERE title LIKE ? OR author LIKE ? OR isbn LIKE ? OR category LIKE ?';$term="%$q%";$params=[$term,$term,$term,$term];}$sql.=' ORDER BY title';$s=$pdo->prepare($sql);$s->execute($params);$rows=$s->fetchAll();}
$pageTitle='Books';require 'includes/header.php'; ?>
<?php if(in_array($action,['add','edit'])): ?><div class="heading"><div><h1><?= $action==='edit'?'Edit book':'Add a book' ?></h1><p>Maintain a searchable catalogue.</p></div><a class="btn btn-outline-secondary" href="books.php">Back</a></div>
<?php if($errors): ?><div class="alert alert-danger"><?php foreach($errors as $er)echo '<div>'.e($er).'</div>'; ?></div><?php endif; ?>
<form method="post" class="panel"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="form_action" value="<?= $action==='edit'?'update':'create' ?>"><input type="hidden" name="id" value="<?= $id ?>"><div class="row g-3">
<?php foreach(['title'=>'Title','author'=>'Author','isbn'=>'ISBN','category'=>'Category'] as $k=>$label): ?><div class="col-md-6"><label class="form-label"><?= e($label) ?> *</label><input class="form-control" name="<?= e($k) ?>" required maxlength="<?= $k==='title'?150:($k==='author'?100:($k==='isbn'?20:80)) ?>" value="<?= e((string)$book[$k]) ?>"></div><?php endforeach; ?>
<div class="col-md-4"><label class="form-label">Total copies *</label><input type="number" min="0" class="form-control" name="quantity" required value="<?= e((string)$book['quantity']) ?>"></div></div><button class="btn btn-primary mt-4">Save book</button></form>
<?php else: ?><div class="heading"><div><h1>Books</h1><p>Search and manage the library catalogue.</p></div><a class="btn btn-primary" href="books.php?action=add">+ Add book</a></div><form class="search mb-3" method="get"><input class="form-control" name="q" value="<?= e($q) ?>" placeholder="Search title, author, ISBN or category"><button class="btn btn-outline-primary">Search</button></form>
<div class="panel p-0 overflow-hidden"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Title</th><th>Author</th><th>ISBN</th><th>Category</th><th>Total</th><th>Available</th><th>Actions</th></tr></thead><tbody>
<?php foreach($rows as $r): ?><tr><td><?= e($r['title']) ?></td><td><?= e($r['author']) ?></td><td><?= e($r['isbn']) ?></td><td><?= e($r['category']) ?></td><td><?= (int)$r['quantity'] ?></td><td><?= (int)$r['available'] ?></td><td><a class="btn btn-sm btn-outline-primary" href="books.php?action=edit&id=<?= (int)$r['id'] ?>">Edit</a> <form class="d-inline" method="post" onsubmit="return confirm('Delete this book?')"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="form_action" value="delete"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach; ?>
<?php if(!$rows): ?><tr><td colspan="7" class="text-center py-4 text-secondary">No books found.</td></tr><?php endif; ?></tbody></table></div></div><?php endif; ?>
<?php require 'includes/footer.php'; ?>
